function Chat({ userId }) {
  const [msgs, setMsgs] = useState([]);
  useEffect(() => {
    const conn = connect(userId);
    conn.onMessage(m => setMsgs([...msgs, m]));
    return () => conn.close();
  }, [userId]);
}

